  'republican': <OpenCetRichExampleRow>[
    OpenCetRichExampleRow(
      exampleId: 'tatoeba:1126262:1957391',
      sourceId: 'tatoeba-cc-by-2.0-fr',
      englishText: 'There are two major political parties in the United States: the conservative Republican Party, and the liberal Democratic Party.',
      chineseText: '美国有两大政党，一是较为保守的共和党，一是较为自由的民主党。',
      englishUsername: 'AlanF_US',
