    ),
    OpenCetRichExampleRow(
      exampleId: 'tatoeba:347742:347811',
      sourceId: 'tatoeba-cc-by-2.0-fr',
      englishText: 'It\'s the answer spoken by young and old, rich and poor, Democrat and Republican, black, white, Hispanic, Asian, Native American, gay, straight, disabled and not disabled. Americans who sent a message to the world that we have never been just a collection of individuals or a collection of red states and blue states. We are, and always will be, the United States of America.',
      chineseText: '這是個由不分老少、貧富、民主黨、共和黨；黑人、白人、拉丁裔、亞裔、美洲原住民；同性戀、異性戀人；肢障與四體健全者，大家共同訴說的答案。美國民眾向全世界發出訊息，我們絕非一盤散沙，也不是由紅州、藍州拼湊而成的集合體。',
      englishUsername: 'U2FS',
      chineseUsername: 'Martha',
    ),
    OpenCetRichExampleRow(
      exampleId: 'tatoeba:347780:347861',
      sourceId: 'tatoeba-cc-by-2.0-fr',
      englishText: 'Let\'s remember that it was a man from this state who first carried the banner of the Republican Party to the White House, a party founded on the values of self-reliance and individual liberty and national unity. Those are values that we all share. And while the Democratic Party has won a great victory tonight, we do so with a measure of humility and determination to heal the divides that have held back our progress.',
      chineseText: '让我们记住，是伊利诺伊州的一名男子首次将共和党的旗帜扛到了白宫。共和党是建立在自立、个人自由以及国家团结的价值观之上的。这也是我们所有人共同的价值观。虽然民主党今天晚上赢得了巨大的胜利，但我们是以谦卑的态度和弥合阻碍我们进步的分歧的决心赢得这场胜利的',
      englishUsername: '\\N',
      chineseUsername: 'zhouj1955',
    ),
  ],
